import csv

# Find driverId 62's races from driverStandings
driver_id = 62
yoong_races = []
with open('csv/driverStandings.csv','r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        if int(row['driverId']) == driver_id:
            yoong_races.append(int(row['raceId']))

print(f"Alex Yoong participated in {len(yoong_races)} races")
print(f"Race IDs: {yoong_races[:10]}...")

# Now get race details for these races
race_details = {}
with open('csv/races.csv','r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        race_id = int(row['raceId'])
        if race_id in yoong_races:
            race_details[race_id] = {
                'name': row['name'],
                'round': int(row['round']),
                'year': row['year']
            }

print("\nRaces with round < 20:")
for race_id, details in race_details.items():
    if details['round'] < 20:
        print(f"  Race ID {race_id}: {details['name']} (Round {details['round']}, Year {details['year']})")

